import sys

MOD = 998244353
G = 3


def ntt(a, invert=False):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(G, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)

        half = length >> 1
        for i in range(0, n, length):
            w = 1
            end = i + half
            for j in range(i, end):
                u = a[j]
                v = a[j + half] * w % MOD
                a[j] = (u + v) % MOD
                a[j + half] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def convolution(a, b):
    if not a or not b:
        return []
    if min(len(a), len(b)) <= 32:
        res = [0] * (len(a) + len(b) - 1)
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    res[i + j] = (res[i + j] + x * y) % MOD
        return res

    need = len(a) + len(b) - 1
    n = 1
    while n < need:
        n <<= 1

    fa = a + [0] * (n - len(a))
    fb = b + [0] * (n - len(b))
    ntt(fa)
    ntt(fb)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    ntt(fa, True)
    return fa[:need]


def main():
    input = sys.stdin.readline
    n = int(input())
    s = input().strip()
    m = 2 * n

    pref_w = [0] * (m + 1)
    pref_b = [0] * (m + 1)
    for i, ch in enumerate(s, 1):
        pref_w[i] = pref_w[i - 1] + (ch == 'W')
        pref_b[i] = pref_b[i - 1] + (ch == 'B')

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (n + 1)
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    dp = [0] * (m + 1)
    raw = [0] * (m + 1)
    dp[0] = 1

    sys.setrecursionlimit(1_000_000)

    def solve(l, r):
        if r - l == 1:
            if l != 0 and l != m:
                dp[l] = (-raw[l]) % MOD
            return

        mid = (l + r) >> 1
        solve(l, mid)

        eligible = []
        cmin = n + 1
        cmax = -1

        for p in range(l, mid):
            if pref_b[p] <= pref_w[p]:
                c = pref_b[p]
                val = dp[p] * invfact[pref_w[p] - pref_b[p]] % MOD
                eligible.append((c, val))
                if c < cmin:
                    cmin = c
                if c > cmax:
                    cmax = c

        if eligible:
            q = [0] * (cmax - cmin + 1)
            for c, val in eligible:
                q[c - cmin] = (q[c - cmin] + val) % MOD

            amax = pref_w[r - 1]
            kernel = fact[:amax - cmin + 1]
            conv = convolution(q, kernel)

            for x in range(mid, r):
                a = pref_w[x]
                idx = a - cmin
                if 0 <= idx < len(conv):
                    raw[x] = (raw[x] + conv[idx]) % MOD

        solve(mid, r)

    solve(0, m + 1)
    print(raw[m] % MOD)


if __name__ == "__main__":
    main()

from typing import List


class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        max_sum = 12 * n

        if k < -max_sum or k > max_sum:
            return -1

        offset = max_sum

        # even[p] and odd[p] are bitsets of achievable alternating sums
        # for subsequences with product p and even/odd length respectively.
        even = [0] * (limit + 1)
        odd = [0] * (limit + 1)

        for value in nums:
            old_even = even[:]
            old_odd = odd[:]

            # Start a new subsequence containing only this value.
            odd[value] |= 1 << (offset + value)

            for product in range(limit + 1):
                e = old_even[product]
                o = old_odd[product]

                if not e and not o:
                    continue

                new_product = product * value
                if new_product > limit:
                    continue

                # Appending to an even-length subsequence adds the value.
                if e:
                    even[new_product] |= e << value

                # Appending to an odd-length subsequence subtracts the value.
                if o:
                    odd[new_product] |= o >> value

        target_bit = 1 << (offset + k)

        for product in range(limit, -1, -1):
            if (even[product] & target_bit) or (odd[product] & target_bit):
                return product

        return -1

