    present = [False] * 26

    for a, b in zip(s, t):
        x = ord(a) - ord('a')
        y = ord(b) - ord('a')
        present[x] = True
        if mapping[x] == -1:
            mapping[x] = y
        elif mapping[x] != y:
            print(-1)
            return

    active = [i for i in range(26) if present[i]]
    changes = sum(mapping[i] != i for i in active)

    state = [0] * 26
    cycles = 0

    for start in active:
        if state[start] != 0 or mapping[start] == start:
            continue

        cur = start
        local = {}

        while cur in active and state[cur] == 0:
            state[cur] = 1
            local[cur] = len(local)
            cur = mapping[cur]

        if cur in local:
            cycles += 1

        for node in local:
            state[node] = 2

    target_values = [mapping[i] for i in active]

    if len(active) == 26 and len(set(target_values)) == 26 and cycles > 0:
        print(-1)
    else:
        print(changes + cycles)


