import sys


def rectangle_cycle(width, height):
    """Return vertices of the perimeter of a width x height rectangle."""
    res = []

    for x in range(width + 1):
        res.append((x, 0))
    for y in range(1, height + 1):
        res.append((width, y))
    for x in range(width - 1, -1, -1):
        res.append((x, height))
    for y in range(height - 1, 0, -1):
        res.append((0, y))

    return res


def solve_case(R, B):
    if R % 2 == 1:
        return None

    # Only blue pieces.
    if R == 0:
        if B == 2:
            xy = [(0, 0), (1, 1)]
        else:
            k = B // 2
            uv = rectangle_cycle(1, k - 1)
            xy = [(u + v, u - v) for u, v in uv]

        shift = 500000000
        return [('B', y + shift, x + shift) for x, y in xy]

    # Only red pieces.
    if B == 0:
        if R == 2:
            xy = [(0, 0), (1, 0)]
        else:
            k = R // 2
            xy = rectangle_cycle(1, k - 1)

        shift = 500000000
        return [('R', y + shift, x + shift) for x, y in xy]

    # Construct a blue path from A=(0,0) to D.
    # In (u,v)-coordinates, a diagonal move is an axis move:
    # x = u+v, y = u-v.
    if B % 2 == 0:
        k = B // 2
        uv = [(0, 0)]
        for v in range(1, k + 1):
            uv.append((0, v))
        uv.append((1, k))
        for v in range(k - 1, 0, -1):
            uv.append((1, v))

        blue = [(u + v, u - v) for u, v in uv]
        dx, dy = 2, 0
    else:
        k = B // 2
        uv = [(0, 0)]
        for v in range(1, k + 1):
            uv.append((0, v))
        uv.append((1, k))
        for v in range(k - 1, -1, -1):
            uv.append((1, v))

        blue = [(u + v, u - v) for u, v in uv]
        dx, dy = 1, 1

    # Construct a red path from D back to A.
    m = R // 2
    red_internal = []

    if B % 2 == 0:
        # D=(2,0): go upward, left, then downward.
        for y in range(1, m):
            red_internal.append((2, y))
        red_internal.append((1, m - 1))
        if m - 1 > 0:
            red_internal.append((0, m - 1))
            for y in range(m - 2, 0, -1):
                red_internal.append((0, y))
    else:
        # D=(1,1): go upward, left, then downward.
        if m == 1:
            red_internal.append((1, 0))
        else:
            for y in range(2, m + 1):
                red_internal.append((1, y))
            red_internal.append((0, m))
            for y in range(m - 1, 0, -1):
                red_internal.append((0, y))

    vertices = blue + red_internal

    shift = 500000000
    answer = []
    for i, (x, y) in enumerate(vertices):
        color = 'B' if i < B else 'R'
        answer.append((color, y + shift, x + shift))

    return answer


def main():
    input = sys.stdin.readline
    t = int(input())
    out = []

    for _ in range(t):
        R, B = map(int, input().split())
        ans = solve_case(R, B)

        if ans is None:
            out.append("No")
        else:
            out.append("Yes")
            for color, r, c in ans:
                out.append(f"{color} {r} {c}")

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

