class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def prefix_sum(n: int) -> int:
            if n <= 0:
                return 0

            total = 0
            start = 1
            operations = 1

            while start <= n:
                end = min(n, start * 4 - 1)
                total += (end - start + 1) * operations
                start *= 4
                operations += 1

            return total

        answer = 0

        for left, right in queries:
            required = prefix_sum(right) - prefix_sum(left - 1)
            answer += (required + 1) // 2

        return answer

