from collections import deque

def solve():
    input = sys.stdin.readline
    n, m = map(int, input().split())

    graph = [[] for _ in range(n)]
    for _ in range(m):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        graph[u].append(v)
        graph[v].append(u)

    color = [-1] * n
    missing_inside = 0
    odd_components = 0

    for start in range(n):
        if color[start] != -1:
            continue

        color[start] = 0
        cnt = [1, 0]
        queue = deque([start])

        while queue:
            v = queue.popleft()
            for to in graph[v]:
                if color[to] == -1:
                    color[to] = color[v] ^ 1
                    cnt[color[to]] += 1
                    queue.append(to)

        missing_inside += cnt[0] * cnt[1]
        if (cnt[0] + cnt[1]) % 2 == 1:
            odd_components += 1

    missing_inside -= m

    if missing_inside % 2 == 1:
        print("Aoki")
    elif odd_components == 0 or odd_components % 4 == 3:
        print("Takahashi")
    else:
        print("Aoki")

