from functools import lru_cache


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(n: int, target_sum: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            length = len(digits)

            @lru_cache(None)
            def suffix(remaining: int, need: int, remainder: int, started: bool) -> int:
                if need < 0 or need > 9 * remaining:
                    return 0

                if remaining == 0:
                    return int(need == 0 and started and remainder == 0)

                total = 0

                if not started:
                    total += suffix(remaining - 1, need, 1, False)
                    for digit in range(1, 10):
                        if digit <= need:
                            total += suffix(
                                remaining - 1,
                                need - digit,
                                digit % target_sum,
                                True,
                            )
                else:
                    for digit in range(10):
                        if digit <= need:
                            total += suffix(
                                remaining - 1,
                                need - digit,
                                (remainder * digit) % target_sum,
                                True,
                            )

                return total

            result = 0
            need = target_sum
            remainder = 1
            started = False

            for index, limit in enumerate(digits):
                remaining = length - index - 1

                for digit in range(limit):
                    if digit > need:
                        break

                    if not started and digit == 0:
                        result += suffix(remaining, need, 1, False)
                    elif not started:
                        result += suffix(
                            remaining,
                            need - digit,
                            digit % target_sum,
                            True,
                        )
                    else:
                        result += suffix(
                            remaining,
                            need - digit,
                            (remainder * digit) % target_sum,
                            True,
                        )

                if limit > need:
                    return result

                if not started and limit == 0:
                    pass
                elif not started:
                    started = True
                    remainder = limit % target_sum
                else:
                    remainder = (remainder * limit) % target_sum

                need -= limit

            if need == 0 and started and remainder == 0:
                result += 1

            return result

        max_sum = 9 * len(str(r))
        total = 0

        for digit_sum in range(1, max_sum + 1):
            total += count_up_to(r, digit_sum)
            total -= count_up_to(l - 1, digit_sum)

        return total

from typing import List


class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        children = [{}]
        count = [0]
        depth = [0]
        endpoints = []

        for word in words:
            node = 0
            count[node] += 1
            for ch in word:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)
                node = nxt
                count[node] += 1
            endpoints.append(node)

        total_nodes = len(children)

        # Compute Euler tour intervals for ancestor checks.
        tin = [0] * total_nodes
        tout = [0] * total_nodes
        timer = 0
        stack = [(0, 0)]

        while stack:
            node, state = stack.pop()
            if state == 0:
                tin[node] = timer
                timer += 1
                stack.append((node, 1))
                for child in children[node].values():
                    stack.append((child, 0))
            else:
                tout[node] = timer

        max_depth = max(depth)
        good_count = [0] * (max_depth + 1)
        unique_node = [-1] * (max_depth + 1)

        for node in range(1, total_nodes):
            if count[node] >= k:
                d = depth[node]
                if good_count[d] == 0:
                    good_count[d] = 1
                    unique_node[d] = node
                else:
                    good_count[d] = 2
                    unique_node[d] = -1

        # Depths that always remain possible after removing any one word.
        baseline = 0
        marked_nodes = []

        for d in range(1, max_depth + 1):
            if good_count[d] >= 2:
                baseline = d
            elif good_count[d] == 1:
                node = unique_node[d]
                if count[node] > k:
                    baseline = d
                else:
                    # This node disappears exactly when the removed word
                    # has this node as a prefix.
                    marked_nodes.append(node)

        # For each marked node, update all Euler positions outside its subtree.
        # A point query then gives the deepest marked node that is not an ancestor.
        size = 1
        while size < total_nodes:
            size <<= 1
        lazy = [0] * (2 * size)

        def range_chmax(left: int, right: int, value: int) -> None:
            left += size
            right += size
            while left < right:
                if left & 1:
                    if lazy[left] < value:
                        lazy[left] = value
                    left += 1
                if right & 1:
                    right -= 1
                    if lazy[right] < value:
                        lazy[right] = value
                left >>= 1
                right >>= 1

        for node in marked_nodes:
            l, r = tin[node], tout[node]
            if l > 0:
                range_chmax(0, l, depth[node])
            if r < total_nodes:
                range_chmax(r, total_nodes, depth[node])

        def point_query(pos: int) -> int:
            pos += size
            result = 0
            while pos:
                if lazy[pos] > result:
                    result = lazy[pos]
                pos >>= 1
            return result

        answer = []
        for endpoint in endpoints:
            answer.append(max(baseline, point_query(tin[endpoint])))

        return answer

