import math

def solve():
    n = int(sys.stdin.readline().strip())

    for d in range(1, 1_000_001):
        if d * d * d >= n:
            break
        if n % d != 0:
            continue

        q = n // d
        discriminant = 12 * q - 3 * d * d
        if discriminant < 0:
            continue

        root = math.isqrt(discriminant)
        if root * root != discriminant:
            continue

        numerator = root - 3 * d
        if numerator <= 0 or numerator % 6 != 0:
            continue

        y = numerator // 6
        x = y + d

        if y > 0 and x * x * x - y * y * y == n:
            print(x, y)
            return

    print(-1)

