import sys
from collections import deque

sys.setrecursionlimit(1_000_000)

class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        fwd = [to, cap, None]
        rev = [fr, 0, fwd]
        fwd[2] = rev
        self.g[fr].append(fwd)
        self.g[to].append(rev)

    def max_flow(self, s, t):
        flow = 0
        INF = 10**18

        while True:
            level = [-1] * self.n
            level[s] = 0
            q = deque([s])

            while q:
                v = q.popleft()
                for to, cap, _ in self.g[v]:
                    if cap > 0 and level[to] < 0:
                        level[to] = level[v] + 1
                        q.append(to)

            if level[t] < 0:
                break

            it = [0] * self.n

            def dfs(v, f):
                if v == t:
                    return f
                while it[v] < len(self.g[v]):
                    e = self.g[v][it[v]]
                    to, cap, rev = e
                    if cap > 0 and level[v] + 1 == level[to]:
                        ret = dfs(to, min(f, cap))
                        if ret:
                            e[1] -= ret
                            rev[1] += ret
                            return ret
                    it[v] += 1
                return 0

            while True:
                f = dfs(s, INF)
                if f == 0:
                    break
                flow += f

        return flow


def main():
    input = sys.stdin.readline
    n, m, k = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(m)]
    edges = [(u - 1, v - 1) for u, v in edges]

    INF = 10**9

    def feasible(d):
        if d == 0:
            return True

        layers = n * d
        source = layers
        sink = layers + 1
        dinic = Dinic(layers + 2)

        def node(v, level):
            return v * d + level - 1

        # Enforce that threshold variables for each vertex are monotone.
        for v in range(n):
            for level in range(1, d):
                dinic.add_edge(node(v, level + 1), node(v, level), INF)

        # Fix x_1 = 0 and x_N = d.
        for level in range(1, d + 1):
            dinic.add_edge(source, node(n - 1, level), INF)
            dinic.add_edge(node(0, level), sink, INF)

        # Encode every original directed edge u -> v.
        for u, v in edges:
            for level in range(1, d + 1):
                # Cost 1 when x_v >= level but x_u < level.
                dinic.add_edge(node(v, level), node(u, level), 1)

            for level in range(1, d):
                # Enforce x_v <= x_u + 1.
                dinic.add_edge(node(v, level + 1), node(u, level), INF)

        return dinic.max_flow(source, sink) <= k

    low, high = 0, n
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)


if __name__ == "__main__":
    main()

import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, k = data[0], data[1]
    v = n * k

    if k == 1:
        print("Yes")
        return

    graph = [[] for _ in range(v)]
    idx = 2
    for _ in range(v - 1):
        a = data[idx] - 1
        b = data[idx + 1] - 1
        idx += 2
        graph[a].append(b)
        graph[b].append(a)

    parent = [-1] * v
    order = [0]
    for x in order:
        for y in graph[x]:
            if y != parent[x]:
                parent[y] = x
                order.append(y)

    open_set = [0] * v
    closed = [False] * v

    mask = (1 << k) - 1
    target = k - 1
    target_mask = (1 << target) - 1

    def has_pair(a, b):
        if a.bit_count() > b.bit_count():
            a, b = b, a

        x = a & target_mask
        while x:
            bit = x & -x
            s = bit.bit_length() - 1
            t = target - s
            if (b >> t) & 1:
                return True
            x -= bit
        return False

    for x in reversed(order):
        child_sets = []
        bad_children = []

        for y in graph[x]:
            if parent[y] == x:
                child_sets.append(open_set[y])
                if not closed[y]:
                    bad_children.append(open_set[y])

        bad = len(bad_children)

        if bad >= 2:
            possible_open = 0
        elif bad == 1:
            possible_open = (bad_children[0] << 1) & mask
        else:
            possible_open = 1
            for s in child_sets:
                possible_open |= (s << 1) & mask

        can_close = False

        if bad == 0:
            if target == 0:
                can_close = True
            else:
                for s in child_sets:
                    if (s >> target) & 1:
                        can_close = True
                        break

                if not can_close:
                    previous = 0
                    for s in child_sets:
                        if has_pair(previous, s):
                            can_close = True
                            break
                        previous |= s

        elif bad == 1:
            required = bad_children[0]
            if (required >> target) & 1:
                can_close = True
            else:
                others = 0
                for s in child_sets:
                    if s is not required:
                        others |= s
                if has_pair(required, others):
                    can_close = True

        else:  # bad == 2
            if has_pair(bad_children[0], bad_children[1]):
                can_close = True

        open_set[x] = possible_open
        closed[x] = can_close

    print("Yes" if closed[0] else "No")


