class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]

        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            events[b].append((a, idx))

        gain = [0] * len(conflictingPairs)

        max_a = 0
        max_id = -1
        second_a = 0
        second_id = -1

        base = 0

        for right in range(1, n + 1):
            for a, idx in events[right]:
                if a > max_a:
                    second_a, second_id = max_a, max_id
                    max_a, max_id = a, idx
                elif a > second_a:
                    second_a, second_id = a, idx

            base += right - max_a

            if max_id != -1:
                gain[max_id] += max_a - second_a

        return base + max(gain)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # KMP failure function
        fail = [0] * m
        for i in range(1, m):
            j = fail[i - 1]
            while j > 0 and str2[i] != str2[j]:
                j = fail[j - 1]
            if str2[i] == str2[j]:
                j += 1
            fail[i] = j

        # KMP transitions for states 0 .. m-1
        nxt = [[0] * 26 for _ in range(m)]
        is_match = [[False] * 26 for _ in range(m)]

        for state in range(m):
            for ci in range(26):
                ch = chr(97 + ci)
                if ch == str2[state]:
                    k = state + 1
                    if k == m:
                        is_match[state][ci] = True
                        k = fail[m - 1]
                    nxt[state][ci] = k
                elif state == 0:
                    nxt[state][ci] = 0
                else:
                    prev = fail[state - 1]
                    nxt[state][ci] = nxt[prev][ci]

        all_masks = [0] * m
        nonmatch_masks = [0] * m

        for state in range(m):
            all_mask = 0
            nonmatch_mask = 0
            for ci in range(26):
                dest = nxt[state][ci]
                bit = 1 << dest
                all_mask |= bit
                if not is_match[state][ci]:
                    nonmatch_mask |= bit
            all_masks[state] = all_mask
            nonmatch_masks[state] = nonmatch_mask

        # viable[pos] is the set of KMP states from which positions
        # pos..L-1 can still be completed validly.
        viable = [0] * (L + 1)
        viable[L] = (1 << m) - 1

        for pos in range(L - 1, -1, -1):
            future = viable[pos + 1]

            if pos < m - 1:
                prev_mask = 0
                for state in range(m):
                    if all_masks[state] & future:
                        prev_mask |= 1 << state
                viable[pos] = prev_mask
                continue

            constraint = str1[pos - m + 1]

            if constraint == 'T':
                # The current state must be m-1 and the next character
                # must complete str2.
                fallback_state = fail[m - 1]
                if future & (1 << fallback_state):
                    viable[pos] = 1 << (m - 1)
                else:
                    viable[pos] = 0
            else:
                prev_mask = 0
                for state in range(m):
                    if nonmatch_masks[state] & future:
                        prev_mask |= 1 << state
                viable[pos] = prev_mask

        if not (viable[0] & 1):
            return ""

        result = []
        state = 0

        for pos in range(L):
            future = viable[pos + 1]
            constrained = pos >= m - 1
            wants_match = constrained and str1[pos - m + 1] == 'T'

            chosen = -1
            next_state = 0

            for ci in range(26):
                if wants_match:
                    if state != m - 1 or ci != ord(str2[-1]) - 97:
                        continue
                    if not is_match[state][ci]:
                        continue
                elif constrained:
                    if is_match[state][ci]:
                        continue

                dest = nxt[state][ci]
                if future & (1 << dest):
                    chosen = ci
                    next_state = dest
                    break

            if chosen == -1:
                return ""

            result.append(chr(97 + chosen))
            state = next_state

        return ''.join(result)

