class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odd_count = (n + 1) // 2
        even_count = n // 2

        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = factorial[i - 1] * i

        used = [False] * (n + 1)
        result = []

        remaining_odd = odd_count
        remaining_even = even_count
        expected_parity = None  # None at the first position

        def count_completions(next_parity: int, ro: int, re: int) -> int:
            remaining = ro + re

            if remaining == 0:
                return 1

            if next_parity == 1:
                if not (ro == re or ro == re + 1):
                    return 0
            else:
                if not (re == ro or re == ro + 1):
                    return 0

            return factorial[ro] * factorial[re]

        for _ in range(n):
            chosen = False

            for value in range(1, n + 1):
                if used[value]:
                    continue

                parity = value % 2

                if expected_parity is not None and parity != expected_parity:
                    continue

                ro = remaining_odd - (parity == 1)
                re = remaining_even - (parity == 0)
                next_parity = 1 - parity

                completions = count_completions(next_parity, ro, re)

                if completions == 0:
                    continue

                if k > completions:
                    k -= completions
                    continue

                used[value] = True
                result.append(value)
                remaining_odd = ro
                remaining_even = re
                expected_parity = next_parity
                chosen = True
                break

            if not chosen:
                return []

        return result

