def compose(r1, r2):
    res = 0
    for a in range(2):
        for b in range(2):
            if r1 & (1 << (2 * a + b)):
                for c in range(2):
                    for d in range(2):
                        if b == c and (r2 & (1 << (2 * c + d))):
                            res |= 1 << (2 * a + d)
    return res

# Relation masks for q = d_i - 1.
# Each mask contains pairs (previous cycle bit, next cycle bit).
inactive_edges = [
    (1 << 1),                 # q = -1: (0, 1)
    (1 << 0) | (1 << 3),      # q =  0: (0, 0), (1, 1)
    (1 << 2),                 # q =  1: (1, 0)
]

active_edges = [
    (1 << 1),                             # q = -1
    (1 << 0) | (1 << 1) | (1 << 3),       # q =  0
    (1 << 0) | (1 << 2) | (1 << 3),       # q =  1
    (1 << 2),                             # q =  2
]

identity = (1 << 0) | (1 << 3)

# Find all nonempty relation masks reachable from the initial identity.
reachable = {identity}
stack = [identity]
while stack:
    cur = stack.pop()
    for edge in inactive_edges + active_edges:
        nxt = compose(cur, edge)
        if nxt and nxt not in reachable:
            reachable.add(nxt)
            stack.append(nxt)

states = sorted(reachable)
index = {mask: i for i, mask in enumerate(states)}
m = len(states)

# For each state and character type, store (next_state, multiplicity).
trans = []
for edges in (inactive_edges, active_edges):
    table = []
    for cur in states:
        count = {}
        for edge in edges:
            nxt = compose(cur, edge)
            if nxt:
                j = index[nxt]
                count[j] = count.get(j, 0) + 1
        table.append(list(count.items()))
    trans.append(table)

