from typing import List


class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side
        positions = []

        for x, y in points:
            if y == 0:
                t = x
            elif x == side:
                t = side + y
            elif y == side:
                t = 3 * side - x
            else:
                t = 4 * side - y
            positions.append(t)

        positions.sort()
        n = len(positions)

        def feasible(dist: int) -> bool:
            if dist == 0:
                return True

            extended = positions + [p + perimeter for p in positions]
            total = 2 * n

            nxt = [total] * (total + 1)
            for i in range(total):
                nxt[i] = bisect_left(extended, extended[i] + dist)

            levels = [(nxt)]
            max_bit = (k - 1).bit_length()
            for _ in range(1, max_bit):
                prev = levels[-1]
                cur = [total] * (total + 1)
                for i in range(total + 1):
                    cur[i] = prev[prev[i]]
                levels.append(cur)

            for start in range(n):
                idx = start
                steps = k - 1
                bit = 0

                while steps:
                    if steps & 1:
                        idx = levels[bit][idx]
                        if idx >= total:
                            break
                    steps >>= 1
                    bit += 1

                if idx < start + n:
                    if extended[idx] - extended[start] <= perimeter - dist:
                        return True

            return False

        low, high = 0, side + 1
        while low + 1 < high:
            mid = (low + high) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid

        return low

