def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    graph = [[] for _ in range(n)]
    p = 1
    for _ in range(n - 1):
        a = data[p] - 1
        b = data[p + 1] - 1
        p += 2
        graph[a].append(b)
        graph[b].append(a)

    parent = [-1] * n
    order = [0]
    parent[0] = -2

    for v in order:
        for u in graph[v]:
            if u != parent[v]:
                parent[u] = v
                order.append(u)

    down_branch = [-1] * n

    for v in reversed(order):
        values = []
        for u in graph[v]:
            if parent[u] == v:
                values.append(max(1, down_branch[u]))

        if len(values) >= 3:
            values.sort(reverse=True)
            down_branch[v] = 1 + values[0] + values[1] + values[2]

    up_branch = [-1] * n
    answer = -1

    for v in order:
        items = []

        if parent[v] >= 0:
            items.append((max(1, up_branch[v]), parent[v], up_branch[v]))

        for u in graph[v]:
            if parent[u] == v:
                items.append((max(1, down_branch[u]), u, down_branch[u]))

        items.sort(reverse=True)

        if len(items) >= 4:
            candidate = 1 + sum(items[i][0] for i in range(4))
            answer = max(answer, candidate)

        if len(items) >= 1:
            for _, _, branch_value in items:
                if branch_value != -1:
                    answer = max(answer, 1 + branch_value)

        for u in graph[v]:
            if parent[u] != v:
                continue

            total = 0
            count = 0
            for value, neighbor, _ in items:
                if neighbor == u:
                    continue
                total += value
                count += 1
                if count == 3:
                    break

            if count == 3:
                up_branch[u] = 1 + total
            else:
                up_branch[u] = -1

    print(answer)

