class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        size = n * m

        # Directions in clockwise order:
        # southeast, southwest, northwest, northeast
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # Phase 0 expects 2, phase 1 expects 0.
        # Straight paths: straight[d][phase][cell]
        straight = [
            [array('H', [0]) * size for _ in range(2)]
            for _ in range(4)
        ]

        # Paths with at most one clockwise turn:
        turned = [
            [array('H', [0]) * size for _ in range(2)]
            for _ in range(4)
        ]

        # Compute straight continuations for every direction.
        for d, (dr, dc) in enumerate(dirs):
            row_range = range(n - 1, -1, -1) if dr == 1 else range(n)
            col_range = range(m - 1, -1, -1) if dc == 1 else range(m)

            s2 = straight[d][0]
            s0 = straight[d][1]

            for r in row_range:
                for c in col_range:
                    idx = r * m + c
                    nr, nc = r + dr, c + dc

                    if 0 <= nr < n and 0 <= nc < m:
                        ni = nr * m + nc
                        next_s2 = s0[ni]
                        next_s0 = s2[ni]
                    else:
                        next_s2 = next_s0 = 0

                    if grid[r][c] == 2:
                        s2[idx] = next_s2 + 1
                    elif grid[r][c] == 0:
                        s0[idx] = next_s0 + 1

        # Compute paths with at most one clockwise turn.
        for d, (dr, dc) in enumerate(dirs):
            clockwise = (d + 1) % 4
            row_range = range(n - 1, -1, -1) if dr == 1 else range(n)
            col_range = range(m - 1, -1, -1) if dc == 1 else range(m)

            t2 = turned[d][0]
            t0 = turned[d][1]
            g2 = straight[clockwise][0]
            g0 = straight[clockwise][1]

            for r in row_range:
                for c in col_range:
                    idx = r * m + c
                    nr, nc = r + dr, c + dc

                    if 0 <= nr < n and 0 <= nc < m:
                        ni = nr * m + nc

                        # If current expects 2, next expects 0.
                        continue_len = t0[ni]
                        turn_len = g0[ni]
                        best_after = max(continue_len, turn_len)
                        if grid[r][c] == 2:
                            t2[idx] = best_after + 1

                        # If current expects 0, next expects 2.
                        continue_len = t2[ni]
                        turn_len = g2[ni]
                        best_after = max(continue_len, turn_len)
                        if grid[r][c] == 0:
                            t0[idx] = best_after + 1
                    else:
                        if grid[r][c] == 2:
                            t2[idx] = 1
                        elif grid[r][c] == 0:
                            t0[idx] = 1

        answer = 0

        # Start at every 1. The next value must be 2.
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue

                answer = max(answer, 1)

                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        ni = nr * m + nc
                        answer = max(answer, 1 + turned[dirs.index((dr, dc))][0][ni])

        return answer

from bisect import bisect_left


class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split("*")
        n = len(s)

        def occurrences(pattern: str):
            if not pattern:
                return list(range(n + 1))

            m = len(pattern)
            lps = [0] * m
            j = 0

            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = lps[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                lps[i] = j

            result = []
            j = 0

            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = lps[j - 1]
                if ch == pattern[j]:
                    j += 1

                if j == m:
                    result.append(i - m + 1)
                    j = lps[j - 1]

            return result

        occ_a = occurrences(a)
        occ_b = occurrences(b)
        occ_c = occurrences(c)

        la, lb, lc = len(a), len(b), len(c)
        answer = n + 1

        for start in occ_a:
            b_index = bisect_left(occ_b, start + la)
            if b_index == len(occ_b):
                continue

            b_start = occ_b[b_index]
            c_index = bisect_left(occ_c, b_start + lb)
            if c_index == len(occ_c):
                continue

            c_start = occ_c[c_index]
            answer = min(answer, c_start + lc - start)

        return -1 if answer == n + 1 else answer

