for i in range(1, max_n + 1):
    fact[i] = fact[i - 1] * i % MOD

inv_fact = [1] * (max_n + 1)
inv_fact[max_n] = pow(fact[max_n], MOD - 2, MOD)
for i in range(max_n, 0, -1):
    inv_fact[i - 1] = inv_fact[i] * i % MOD


def comb(n, k):
    if k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD


def paths_to_point(x, y):
    return (comb(x + y + 2, x + 1) - 1) % MOD


def total_paths(w, h):
    return (
        comb(w + h + 4, h + 2)
        - h
        - 3
        - (w + 1) * (h + 2)
    ) % MOD


def rect_sum_a(x1, x2, y1, y2):
    if x1 > x2 or y1 > y2:
        return 0
    return (
        total_paths(x2, y2)
        - total_paths(x1 - 1, y2)
        - total_paths(x2, y1 - 1)
        + total_paths(x1 - 1, y1 - 1)
    ) % MOD


# Total paths whose start and end are both outside the forbidden rectangle.
all_paths = total_paths(W, H)

starts_in_hole = rect_sum_a(W - R, W - L, H - U, H - D)
ends_in_hole = rect_sum_a(L, R, D, U)
both_in_hole = total_paths(R - L, U - D)

base = (all_paths - starts_in_hole - ends_in_hole + both_in_hole) % MOD

# Subtract paths which start outside, enter the forbidden rectangle,
# and eventually end outside.
bad = 0

if L > 0:
    for y in range(D, U + 1):
        prefix = paths_to_point(L - 1, y)
        suffix = (
            paths_to_point(W - L, H - y)
            - paths_to_point(R - L, U - y)
        ) % MOD
        bad = (bad + prefix * suffix) % MOD

if D > 0:
    for x in range(L, R + 1):
        prefix = paths_to_point(x, D - 1)
        suffix = (
            paths_to_point(W - x, H - D)
            - paths_to_point(R - x, U - D)
        ) % MOD
        bad = (bad + prefix * suffix) % MOD

print((base - bad) % MOD)

