def factorize(x):
    res = []
    d = 2
    while d * d <= x:
        if x % d == 0:
            e = 0
            while x % d == 0:
                x //= d
                e += 1
            res.append((d, e))
        d += 1
    if x > 1:
        res.append((x, 1))
    return res


def main():
    input = sys.stdin.readline
    n = int(input())
    a = list(map(int, input().split()))

    exponents = {}
    for i, x in enumerate(a):
        for p, e in factorize(x):
            if p not in exponents:
                exponents[p] = [0] * (n - 1)
            exponents[p][i] = e

    answer = 1

    for p, es in exponents.items():
        total = sum(es)
        pw = [1] * (total + 1)
        for i in range(1, total + 1):
            pw[i] = pw[i - 1] * p % MOD

        # pref[j]: total weight of paths whose first minimum is at vertex j,
        # considering the prefix up to that vertex.
        pref = [0] * n
        pref[0] = 1

        dp = pw[1:]  # positive starting heights, including weight of vertex 1

        for i, e in enumerate(es):
            if e == 0:
                for h in range(1, total + 1):
                    dp[h - 1] = dp[h - 1] * pw[h] % MOD
            else:
                pref[i + 1] = dp[e - 1] if e <= total else 0
                ndp = [0] * total
                for h in range(1, total + 1):
                    val = 0
                    if h + e <= total:
                        val += dp[h + e - 1]
                    if h - e >= 1:
                        val += dp[h - e - 1]
                    ndp[h - 1] = (val % MOD) * pw[h] % MOD
                dp = ndp

        # suf[j]: total weight of nonnegative paths from vertex j onward,
        # with vertex j having height zero.
        suf = [0] * n
        dp = pw[:]  # weight of the final vertex for every possible height
        suf[n - 1] = 1

        for i in range(n - 2, -1, -1):
            e = es[i]
            if e == 0:
                for h in range(total + 1):
                    dp[h] = dp[h] * pw[h] % MOD
            else:
                ndp = [0] * (total + 1)
                for h in range(total + 1):
                    val = 0
                    if h - e >= 0:
                        val += dp[h - e]
                    if h + e <= total:
                        val += dp[h + e]
                    ndp[h] = (val % MOD) * pw[h] % MOD
                dp = ndp
            suf[i] = dp[0]

        contribution = 0
        for i in range(n):
            contribution = (contribution + pref[i] * suf[i]) % MOD

        answer = answer * contribution % MOD

    print(answer)


