class Solution:
    def countSubstrings(self, s: str) -> int:
        ans = 0
        dp3 = [0] * 3
        dp7 = [0] * 7
        dp9 = [0] * 9

        for i, ch in enumerate(s):
            d = ord(ch) - 48

            new3 = [0] * 3
            for r, count in enumerate(dp3):
                new3[(r * 10 + d) % 3] += count
            new3[d % 3] += 1
            dp3 = new3

            new7 = [0] * 7
            for r, count in enumerate(dp7):
                new7[(r * 10 + d) % 7] += count
            new7[d % 7] += 1
            dp7 = new7

            new9 = [0] * 9
            for r, count in enumerate(dp9):
                new9[(r * 10 + d) % 9] += count
            new9[d % 9] += 1
            dp9 = new9

            if d == 0:
                continue
            elif d in (1, 2, 5):
                ans += i + 1
            elif d in (3, 6):
                ans += dp3[0]
            elif d == 9:
                ans += dp9[0]
            elif d == 7:
                ans += dp7[0]
            elif d == 4:
                ans += 1
                if i >= 1:
                    last_two = (ord(s[i - 1]) - 48) * 10 + d
                    if last_two % 4 == 0:
                        ans += i
            elif d == 8:
                ans += 1
                if i >= 1:
                    last_two = (ord(s[i - 1]) - 48) * 10 + d
                    if last_two % 8 == 0:
                        ans += 1
                if i >= 2:
                    last_three = (
                        (ord(s[i - 2]) - 48) * 100
                        + (ord(s[i - 1]) - 48) * 10
                        + d
                    )
                    if last_three % 8 == 0:
                        ans += i - 1

        return ans

import sys


MOD = 998244353
ROOT = 3


def count_direct(values):
    n = len(values)
    present = set(values)
    ans = 0
    for i in range(n):
        a = values[i]
        for j in range(i + 1, n):
            c = values[j]
            s = a + c
            if (s & 1) == 0 and (s >> 1) in present:
                ans += 1
    return ans


def ntt(a, invert):
    n = len(a)

    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        half = length >> 1
        wlen = pow(ROOT, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)

        roots = [1] * half
        for k in range(1, half):
            roots[k] = roots[k - 1] * wlen % MOD

        for start in range(0, n, length):
            other = start + half
            for k in range(half):
                u = a[start + k]
                v = a[other + k] * roots[k] % MOD
                a[start + k] = (u + v) % MOD
                a[other + k] = (u - v) % MOD

        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:1 + n]

    if n <= 2500:
        print(count_direct(values))
        return

    maximum = max(values)
    size = 1
    while size <= 2 * maximum:
        size <<= 1

    poly = [0] * size
    for x in values:
        poly[x] = 1

    ntt(poly, False)

    for i in range(size):
        poly[i] = poly[i] * poly[i] % MOD

    ntt(poly, True)

    answer = 0
    for x in values:
        answer += (poly[2 * x] - 1) // 2

    print(answer)


