import sys
import math

def make_primes(limit):
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i::i] = b"\x00" * (((limit - i * i) // i) + 1)
    return [i for i in range(2, limit + 1) if sieve[i]]

PRIMES = make_primes(31623)

def factorize(n):
    factors = []
    x = n
    for p in PRIMES:
        if p * p > x:
            break
        if x % p == 0:
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            factors.append((p, e))
        if x == 1:
            break
    if x > 1:
        factors.append((x, 1))
    return factors

def solve_case(n):
    if n == 1:
        return 1, 1

    factors = factorize(n)
    two_exp = 0
    odd_factors = []

    for p, e in factors:
        if p == 2:
            two_exp = e
        else:
            odd_factors.append((p, e))

    components = []

    if two_exp:
        if odd_factors:
            # This component supplies order 2^(two_exp-1).
            mod2 = 1 << (two_exp + 1)
        else:
            # No odd component can supply the missing factor 2.
            mod2 = 1 << (two_exp + 2)
        components.append((mod2, 5 % mod2))

    use_minus = two_exp > 0 and bool(odd_factors)

    for i, (p, e) in enumerate(odd_factors):
        mod = p ** (e + 1)
        residue = 1 + p
        if use_minus and i == 0:
            residue = (-residue) % mod
        components.append((mod, residue))

    x = 0
    current_mod = 1

    for mod, residue in components:
        t = ((residue - x) * pow(current_mod, -1, mod)) % mod
        x += current_mod * t
        current_mod *= mod
        x %= current_mod

    if x == 0:
        x = current_mod

    return x, current_mod

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    out = []

    for i in range(1, t + 1):
        a, m = solve_case(data[i])
        out.append(f"{a} {m}")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

