from bisect import bisect_left

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, X = data[0], data[1]

    groups = [[], [], []]
    idx = 2
    for _ in range(n):
        v, a, c = data[idx], data[idx + 1], data[idx + 2]
        idx += 3
        groups[v - 1].append((a, c))

    def build_dp(items):
        dp = [0] * (X + 1)
        for amount, cost in items:
            for capacity in range(X, cost - 1, -1):
                candidate = dp[capacity - cost] + amount
                if candidate > dp[capacity]:
                    dp[capacity] = candidate
        return dp

    dps = [build_dp(group) for group in groups]

    upper = min(dp[X] for dp in dps)
    low, high = 0, upper + 1

    while high - low > 1:
        mid = (low + high) // 2
        required = [
            bisect_left(dp, mid)
            for dp in dps
        ]

        if sum(required) <= X:
            low = mid
        else:
            high = mid

    print(low)

