from typing import List


class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        limit = k - 1

        def triangle(q: int) -> int:
            return q * (q - 1) // 2 if q > 1 else 0

        def count_subarrays(left: int, right: int) -> int:
            # Number of pairs (l, r) with:
            # 0 <= l <= left, 0 <= r <= right, l + r <= k - 1
            return (
                triangle(limit + 2)
                - triangle(limit - left + 1)
                - triangle(limit - right + 1)
                + triangle(limit - left - right)
            )

        def contribution_for_minimum() -> int:
            previous = [-1] * n
            stack = []

            for i, value in enumerate(nums):
                while stack and nums[stack[-1]] >= value:
                    stack.pop()
                previous[i] = stack[-1] if stack else -1
                stack.append(i)

            next_boundary = [n] * n
            stack = []

            for i in range(n - 1, -1, -1):
                while stack and nums[stack[-1]] > nums[i]:
                    stack.pop()
                next_boundary[i] = stack[-1] if stack else n
                stack.append(i)

            total = 0
            for i, value in enumerate(nums):
                left = i - previous[i] - 1
                right = next_boundary[i] - i - 1
                total += value * count_subarrays(left, right)
            return total

        def contribution_for_maximum() -> int:
            previous = [-1] * n
            stack = []

            for i, value in enumerate(nums):
                while stack and nums[stack[-1]] <= value:
                    stack.pop()
                previous[i] = stack[-1] if stack else -1
                stack.append(i)

            next_boundary = [n] * n
            stack = []

            for i in range(n - 1, -1, -1):
                while stack and nums[stack[-1]] < nums[i]:
                    stack.pop()
                next_boundary[i] = stack[-1] if stack else n
                stack.append(i)

            total = 0
            for i, value in enumerate(nums):
                left = i - previous[i] - 1
                right = next_boundary[i] - i - 1
                total += value * count_subarrays(left, right)
            return total

        return contribution_for_minimum() + contribution_for_maximum()

import sys
import math


def solve():
    N, P = map(int, sys.stdin.readline().split())
    half = N // 2
    degree = N * (N - 1) // 2

    comb = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        for j in range(i + 1):
            comb[i][j] = math.comb(i, j) % P

    values = []

    for x in range(degree + 1):
        r = (x + 1) % P

        rpow = [1] * (N + 1)
        for i in range(1, N + 1):
            rpow[i] = rpow[i - 1] * r % P

        layer_factor = [1] * (N + 1)
        for b in range(1, N + 1):
            layer_factor[b] = layer_factor[b - 1] * rpow[b - 1] % P

        weights = [[0] * (N + 1) for _ in range(N + 1)]
        for a in range(1, N + 1):
            base = (rpow[a] - 1) % P
            powers = [1] * (N + 1)
            for b in range(1, N + 1):
                powers[b] = powers[b - 1] * base % P
            for b in range(1, N + 1):
                weights[a][b] = layer_factor[b] * powers[b] % P

        answer = 0
        current = {(1, 1, 1): 1}
        depth = 0

        while current:
            nxt = {}

            for (used, last, even_count), value in current.items():
                if used == N:
                    if even_count == half:
                        answer += value
                        if answer >= P:
                            answer -= P
                    continue

                max_add = N - used
                next_even = ((depth + 1) & 1) == 0

                for b in range(1, max_add + 1):
                    new_even_count = even_count + (b if next_even else 0)
                    if new_even_count > half:
                        continue
                    if new_even_count + (N - used - b) < half:
                        continue

                    w = weights[last][b]
                    if w == 0:
                        continue

                    ways_labels = comb[N - used][b]
                    add = value * w % P * ways_labels % P
                    key = (used + b, b, new_even_count)
                    nxt[key] = (nxt.get(key, 0) + add) % P

            current = nxt
            depth += 1

        values.append(answer % P)

    # Recover coefficients from evaluations at x = 0, 1, ..., degree
    differences = values[:]
    forward = []
    while differences:
        forward.append(differences[0])
        differences = [
            (differences[i + 1] - differences[i]) % P
            for i in range(len(differences) - 1)
        ]

    inv = [0] * (degree + 2)
    inv[1] = 1
    for i in range(2, degree + 2):
        inv[i] = P - (P // i) * inv[P % i] % P

    coefficients = [0] * (degree + 1)
    basis = [1]

    for j in range(degree + 1):
        multiplier = forward[j]
        if multiplier:
            for k, v in enumerate(basis):
                coefficients[k] = (coefficients[k] + multiplier * v) % P

        if j == degree:
            break

        new_basis = [0] * (len(basis) + 1)
        inv_next = inv[j + 1]
        for k in range(len(new_basis)):
            value = 0
            if k > 0:
                value += basis[k - 1]
            if k < len(basis):
                value -= j * basis[k]
            new_basis[k] = value % P * inv_next % P
        basis = new_basis

    print(*coefficients[N - 1:degree + 1])


