import sys
from array import array
import heapq


def solve():
    input = sys.stdin.buffer.readline
    N, M = map(int, input().split())

    intervals = []
    op1_intervals = []
    op2_intervals = []

    for i in range(M):
        l, r = map(int, input().split())
        intervals.append((l, r))
        op1_intervals.append((l, r))
        op2_intervals.append((l, r))

    # Prefix maximum right endpoint and its operation index for Operation 1.
    pref_r = array('i', [0]) * (N + 2)
    pref_idx = array('i', [-1]) * (N + 2)

    start_best = array('i', [0]) * (N + 2)
    start_idx = array('i', [-1]) * (N + 2)

    for idx, (l, r) in enumerate(op1_intervals):
        if r > start_best[l]:
            start_best[l] = r
            start_idx[l] = idx

    cur_r = 0
    cur_idx = -1
    for p in range(1, N + 1):
        if start_best[p] > cur_r:
            cur_r = start_best[p]
            cur_idx = start_idx[p]
        pref_r[p] = cur_r
        pref_idx[p] = cur_idx

    # Binary lifting for greedy interval covering.
    base = array('i', [0]) * (N + 2)
    for p in range(1, N + 1):
        if pref_r[p] >= p:
            base[p] = pref_r[p] + 1
        else:
            base[p] = 0
    base[N + 1] = N + 1

    LOG = max(1, (M + 1).bit_length())
    lift = [base]
    for _ in range(1, LOG):
        prev = lift[-1]
        nxt = array('i', (prev[prev[p]] for p in range(N + 2)))
        lift.append(nxt)

    def cover_count(l, r):
        if l > r:
            return 0
        if pref_r[l] < l:
            return None
        if pref_r[l] >= r:
            return 1

        pos = l
        used = 0

        for k in range(LOG - 1, -1, -1):
            nxt = lift[k][pos]
            if nxt != 0 and nxt <= r:
                pos = nxt
                used += 1 << k

        if pos == 0 or pref_r[pos] < pos:
            return None
        return used + 1

    def greedy_indices(l, r):
        result = []
        while l <= r:
            if pref_r[l] < l:
                return None
            result.append(pref_idx[l])
            l = pref_r[l] + 1
        return result

    best_cost = None
    best_op1 = []
    best_op2 = []

    def update(cost, op1_list, op2_list):
        nonlocal best_cost, best_op1, best_op2
        if cost is not None and (best_cost is None or cost < best_cost):
            best_cost = cost
            best_op1 = op1_list
            best_op2 = op2_list

    # No Operation 2.
    c = cover_count(1, N)
    if c is not None:
        update(c, None, [])

    # Information about Operation 2 intervals.
    max_r_by_l = array('i', [0]) * (N + 2)
    max_idx_by_l = array('i', [-1]) * (N + 2)
    exact_first = {}
    exact_second = {}

    min_l_by_r = {}
    min_l_idx_by_r = {}
    count_by_r = {}

    l_values = set()

    for idx, (l, r) in enumerate(op2_intervals):
        l_values.add(l)

        if r > max_r_by_l[l]:
            max_r_by_l[l] = r
            max_idx_by_l[l] = idx

        key = (l, r)
        if key not in exact_first:
            exact_first[key] = idx
        elif key not in exact_second:
            exact_second[key] = idx

        count_by_r[r] = count_by_r.get(r, 0) + 1
        if r not in min_l_by_r or l < min_l_by_r[r]:
            min_l_by_r[r] = l
            min_l_idx_by_r[r] = idx

    # One Operation 2.
    for idx, (l, r) in enumerate(op2_intervals):
        c = cover_count(l, r)
        if c is not None:
            update(c + 1, None, [idx])

    # Two Operation 2 operations.
    # Process left endpoints increasingly.  At each left endpoint l,
    # find the smallest right endpoint r of an interval with L <= l.
    records = sorted((ml, r) for r, ml in min_l_by_r.items())
    l_sorted = sorted(l_values)
    heap = []
    ptr = 0

    for l in l_sorted:
        while ptr < len(records) and records[ptr][0] <= l:
            heapq.heappush(heap, records[ptr][1])
            ptr += 1

        if not heap:
            continue

        r = heap[0]
        if r > max_r_by_l[l]:
            continue

        b_idx = min_l_idx_by_r[r]
        distinct = False
        a_idx = max_idx_by_l[l]

        if min_l_by_r[r] < l:
            distinct = True
        elif max_r_by_l[l] > r:
            distinct = True
        else:
            cnt = count_by_r.get(r, 0)
            if cnt >= 2:
                key = (l, r)
                if key in exact_second:
                    distinct = True
                    a_idx = exact_first[key]

        if not distinct:
            continue

        c = cover_count(l, r)
        if c is not None:
            update(c + 2, None, [a_idx, b_idx])

    if best_cost is None:
        print(-1)
        return

    selected_op1 = greedy_indices(
        1 if not best_op2 else (
            max(op2_intervals[i][0] for i in best_op2)
        ),
        N if not best_op2 else (
            min(op2_intervals[i][1] for i in best_op2)
        )
    )

    # For the no-Operation-2 case, the above is exactly [1, N].
    # For one/two Operation-2 cases, it is their intersection.
    if selected_op1 is None:
        print(-1)
        return

    ans = [0] * M
    for idx in selected_op1:
        ans[idx] = 1
    for idx in best_op2:
        ans[idx] = 2

    print(best_cost)
    print(*ans)


