        k_zero += sum(x == 0 for x in row)
        a.append(row)

    if p == 2:
        v = n % 2
        out = "\n".join((" ".join([str(v)] * n)) for _ in range(n))
        print(out)
        return

    mod = p

    def matmul(x, y):
        res = [[0] * n for _ in range(n)]
        for i in range(n):
            ri = res[i]
            xi = x[i]
            for k, v in enumerate(xi):
                if v:
                    yk = y[k]
                    for j in range(n):
                        ri[j] += v * yk[j]
            for j in range(n):
                ri[j] %= mod
        return res

    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    base = [row[:] for row in a]
    exp = p

    while exp:
        if exp & 1:
            result = matmul(result, base)
        base = matmul(base, base)
        exp >>= 1

    if p == 3:
        for u in range(n):
            for v in range(n):
                if a[u][v] == 0:
                    if u == v:
                        for i in range(n):
                            result[i][u] += a[i][u]
                        for j in range(n):
                            result[u][j] += a[u][j]
                    else:
                        result[u][v] += a[v][u]
    else:
        for u in range(n):
            if a[u][u] == 0:
                for i in range(n):
                    result[i][u] += a[i][u]
                for j in range(n):
                    result[u][j] += a[u][j]

    sign = 1 if k_zero % 2 == 0 else mod - 1
    for i in range(n):
        for j in range(n):
            result[i][j] = (result[i][j] * sign) % mod

    print("\n".join(" ".join(map(str, row)) for row in result))


