from typing import List
from array import array


class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        prefix = [0] * (n + 1)
        for i, value in enumerate(nums):
            prefix[i + 1] = prefix[i] + value

        # nxt[i] = first index j > i such that nums[j] > nums[i]
        nxt = [n] * n
        stack = []

        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                nxt[i] = stack[-1]
            stack.append(i)

        # total[i] is the cost of processing the complete next-greater chain
        # starting at i.
        total = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            end = nxt[i]
            segment_cost = (
                nums[i] * (end - i) - (prefix[end] - prefix[i])
            )
            total[i] = segment_cost + total[end]

        # Binary lifting over the next-greater chain.
        jumps = [array("i", nxt + [n])]
        while (1 << len(jumps)) <= n:
            previous = jumps[-1]
            jumps.append(
                array("i", (previous[previous[i]] for i in range(n + 1)))
            )

        reversed_jumps = list(reversed(jumps))

        def cost(left: int, right: int) -> int:
            node = left

            for jump in reversed_jumps:
                next_node = jump[node]
                if next_node <= right:
                    node = next_node

            full_cost = total[left] - total[node]
            partial_cost = (
                nums[node] * (right + 1 - node)
                - (prefix[right + 1] - prefix[node])
            )
            return full_cost + partial_cost

        answer = 0
        right = -1

        for left in range(n):
            if right < left - 1:
                right = left - 1

            while right + 1 < n and cost(left, right + 1) <= k:
                right += 1

            answer += right - left + 1

        return answer

import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M, A, B = data[:4]
    intervals = []
    idx = 4
    for _ in range(M):
        L, R = data[idx], data[idx + 1]
        idx += 2
        intervals.append((L, R))

    # If every move has exactly the same length, reachable squares
    # are precisely those congruent to 1 modulo A.
    if A == B:
        step = A
        if (N - 1) % step != 0:
            print("No")
            return

        for L, R in intervals:
            first = L + ((1 - L) % step)
            if first <= R:
                print("No")
                return

        print("Yes")
        return

    # mask bit k represents reachability of the position
    # current_position - B + k.
    full = (1 << B) - 1
    usable = (1 << (B - A + 1)) - 1

    # After at most B*B+B steps in an unrestricted segment,
    # a nonempty reachable state becomes all ones.
    LIMIT = B * B + B + 5

    def advance_allowed(mask, length):
        while length > 0 and mask != 0 and mask != full:
            steps = min(length, LIMIT)
            for _ in range(steps):
                reachable = 1 if (mask & usable) else 0
                mask = (mask >> 1) | (reachable << (B - 1))
            length -= steps

            if length > 0 and mask != 0 and mask != full:
                # This case cannot occur for A < B, but safely handle it
                # by detecting a cycle in the finite state space.
                seen = {}
                while length > 0 and mask != 0 and mask != full:
                    if mask in seen:
                        cycle = seen[mask]
                        cycle_len = seen.get(("len", mask), 0)
                        if cycle_len > 0:
                            skip = (length // cycle_len) * cycle_len
                            length -= skip
                            if skip:
                                continue
                    seen[mask] = seen.get(mask, 0)
                    reachable = 1 if (mask & usable) else 0
                    mask = (mask >> 1) | (reachable << (B - 1))
                    length -= 1
                    for key in list(seen):
                        if isinstance(key, tuple):
                            del seen[key]
                    # The fallback is practically unreachable; the main
                    # bounded simulation handles all valid A < B cases.
                    if length == 0:
                        break

        if mask == full:
            return full
        if mask == 0:
            return 0

        # For valid inputs with A < B, the state must have stabilized here.
        while length > 0:
            reachable = 1 if (mask & usable) else 0
            mask = (mask >> 1) | (reachable << (B - 1))
            length -= 1
        return mask

    def advance_blocked(mask, length):
        if length >= B:
            return 0
        for _ in range(length):
            mask >>= 1
        return mask

    # Position 1 is initially reachable.
    mask = 1 << (B - 1)
    current = 2

    for L, R in intervals:
        # Process the unrestricted segment before [L, R].
        if current < L:
            mask = advance_allowed(mask, L - current)
            if mask == 0:
                print("No")
                return

        # Process the blocked interval.
        mask = advance_blocked(mask, R - L + 1)
        current = R + 1

    # Process the final unrestricted segment through N.
    if current <= N:
        mask = advance_allowed(mask, N - current + 1)

    print("Yes" if (mask & (1 << (B - 1))) else "No")


if __name__ == "__main__":
    solve()

from typing import List
from bisect import bisect_left


class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        items = sorted(
            [(l, r, w, i) for i, (l, r, w) in enumerate(intervals)],
            key=lambda x: x[1]
        )

        n = len(items)
        ends = [item[1] for item in items]

        # dp[k][i] = (maximum score using at most k intervals
        #             among the first i sorted intervals, lexicographically
        #             smallest index tuple achieving that score)
        dp = [[(0, ()) for _ in range(n + 1)] for _ in range(5)]

        for i in range(1, n + 1):
            l, r, weight, original_index = items[i - 1]
            previous = bisect_left(ends, l)  # number of intervals with end < l

            for k in range(1, 5):
                skip = dp[k][i - 1]

                base_score, base_indices = dp[k - 1][previous]
                candidate_indices = tuple(sorted(base_indices + (original_index,)))
                take = (base_score + weight, candidate_indices)

                if take[0] > skip[0] or (
                    take[0] == skip[0] and take[1] < skip[1]
                ):
                    dp[k][i] = take
                else:
                    dp[k][i] = skip

        return list(dp[4][n][1])

