    rows = {}

    for _ in range(M):
        x, y, c = input().split()
        x = int(x)
        y = int(y)

        if x not in rows:
            rows[x] = [0, N]  # [maximum required black prefix, minimum allowed upper bound]

        if c == "B":
            rows[x][0] = max(rows[x][0], y)
        else:
            rows[x][1] = min(rows[x][1], y - 1)

    min_upper = N

    for x in sorted(rows):
        lower, upper = rows[x]
        min_upper = min(min_upper, upper)
        if lower > min_upper:
            print("No")
            return

    print("Yes")

