class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        count = [0] * 26

        for ch in s:
            count[ord(ch) - ord('a')] += 1

        answer = n  # Delete every character.

        for target in range(n + 1):
            cost = 0
            for i in range(26):
                cost += abs(count[i] - target)

            # Changing a character from i to i + 1 saves one operation
            # compared with deleting and inserting, when i has surplus
            # and i + 1 has deficit.
            for i in range(25):
                surplus = max(0, count[i] - target)
                deficit = max(0, target - count[i + 1])
                cost -= min(surplus, deficit)

            answer = min(answer, cost)

        return answer

import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    a = data[1:]

    total = (n + 1) * sum(a)
    answer = total

    max_sum = 2 * max(a)
    modulus = 2

    while modulus <= max_sum:
        mask = modulus - 1
        groups = {}

        for x in a:
            r = x & mask
            item = groups.get(r)
            if item is None:
                groups[r] = [1, x]
            else:
                item[0] += 1
                item[1] += x

        divisible_sum = 0

        for r, (count, value_sum) in groups.items():
            complement = (-r) & mask

            if r > complement:
                continue

            if r == complement:
                divisible_sum += (count + 1) * value_sum
            else:
                other = groups.get(complement)
                if other is not None:
                    other_count, other_sum = other
                    divisible_sum += value_sum * other_count + other_sum * count

        answer -= divisible_sum // modulus
        modulus <<= 1

    print(answer)

