    solve()

import sys
from array import array

def build_tree(values, size, neg):
    tree = array('q', [neg]) * (2 * size)
    for i, v in enumerate(values):
        tree[size + i] = v
    for i in range(size - 1, 0, -1):
        left = tree[i << 1]
        right = tree[i << 1 | 1]
        tree[i] = left if left >= right else right
    return tree

def find_first(tree, size, n, start, threshold):
    if start >= n:
        return n

    pos = start + size
    while pos:
        if pos & 1:
            if tree[pos] >= threshold:
                while pos < size:
                    left = pos << 1
                    if tree[left] >= threshold:
                        pos = left
                    else:
                        pos = left | 1
                result = pos - size
                return result if result < n else n
            pos += 1
        pos >>= 1
    return n

def main():
    input_data = list(map(int, sys.stdin.buffer.read().split()))
    n = input_data[0]
    a = input_data[1:]

    prefix = [0] * (n + 1)
    for i, x in enumerate(a):
        prefix[i + 1] = prefix[i] + x

    size = 1
    while size < n:
        size <<= 1

    neg = -(10 ** 30)

    right_values = [a[i] - prefix[i] for i in range(n)]
    left_values = [a[i] + prefix[i + 1] for i in range(n - 1, -1, -1)]

    right_tree = build_tree(right_values, size, neg)
    left_tree = build_tree(left_values, size, neg)

    answers = [0] * n

    for start in range(n):
        l = r = start

        while True:
            total = prefix[r + 1] - prefix[l]

            if r + 1 < n:
                right_block = find_first(
                    right_tree, size, n, r + 1, total - prefix[r + 1]
                )
                new_r = right_block - 1 if right_block < n else n - 1
            else:
                new_r = r

            if l > 0:
                reversed_start = n - l
                left_block_reversed = find_first(
                    left_tree, size, n, reversed_start, total + prefix[l]
                )
                if left_block_reversed < n:
                    left_block = n - 1 - left_block_reversed
                    new_l = left_block + 1
                else:
                    new_l = 0
            else:
                new_l = l

            if new_r > r:
                r = new_r
            elif new_l < l:
                l = new_l
            else:
                break

        answers[start] = prefix[r + 1] - prefix[l]

    print(*answers)

if __name__ == "__main__":
    main()

