        if j % 2 == 1:
            odd_gaps.append(gap)
        else:
            even_gaps.append(gap)

    odd_gaps.sort()
    even_gaps.sort()

    ans = n * x[0]

    for gap, j in zip(odd_gaps, range(1, n, 2)):
        ans += gap * (n - j)

